#[cfg(test)]mod tests{
use super::*;use serde_json::{Value,json};
fn render(h:&runtime::LiquidBounceHooks,input:&Value)->Value{let mut g=String::new();h.storage_esp(&mod_api::NullHost,&mut mod_api::ClientStorageEspEvent{input:&input.to_string(),geometry:&mut g});if g.is_empty(){Value::Null}else{serde_json::from_str(&g).unwrap()}}
#[test]fn storage_esp_usable(){
 config::roundtrip();let mut s=storage_esp::StorageEsp::default();assert_eq!(s.style,1);assert!(s.glow);for i in 0..9{assert_eq!(s.styles[i].get("Fill"),storage_esp::FILLS[i]);}assert_eq!(s.categories[9].color as u32,0xff9d6e9d);for(i,n)in["chest","trapped_chest","barrel","ender_chest","smoker","brewing_stand","crafter","dropper","hopper","blue_shulker_box","decorated_pot","chiseled_bookshelf","oak_shelf"].into_iter().enumerate(){assert_eq!(storage_esp::block_category(n),Some(i));}assert_eq!(storage_esp::entity_category("minecraft:donkey",false),None);assert_eq!(storage_esp::entity_category("minecraft:donkey",true),Some(0));assert_eq!(storage_esp::entity_category("minecraft:hopper_minecart",false),Some(8));s.set_fade(0,50.);assert_eq!(s.fade[0],0.);s.set_fade(2,50.);s.set_fade(1,10.);s.set_fade(0,5.);assert!((s.fade_at([7.5,0.,0.],[0.;3])-0.5).abs()<1e-6);assert!(!s.within([512.,0.,0.],[0.;3]));
 let blocks=[storage_esp::Block{position:[0,0,0],category:0,boxes:vec![[0.,0.,0.,1.,1.,1.]]},storage_esp::Block{position:[1,0,0],category:0,boxes:vec![[1.,0.,0.,2.,1.,1.]]}];let merged=storage_esp::shapes(&blocks,true);assert_eq!(merged.len(),1);assert_eq!(merged[0].1.quads.len(),6);assert_eq!(merged[0].1.lines.len(),12);assert_eq!(storage_esp::shapes(&blocks,false).len(),2);
 let h=runtime::LiquidBounceHooks::default();let input=json!({"camera":[0.,0.,0.],"eye":[0.,0.,-1.],"blocks":[{"position":[1,0,0],"name":"minecraft:chest","model":true,"boxes":[[1.,0.,0.,2.,1.,1.]]},{"position":[2,0,0],"name":"minecraft:barrel","model":false,"boxes":[[2.,0.,0.,3.,1.,1.]]},{"position":[3,0,0],"name":"minecraft:chest","model":true,"boxes":[[3.,0.,0.,4.,1.,1.]]}],"entities":[{"id":7,"name":"minecraft:chest_boat","position":[4.,0.,0.],"interpolated":[3.5,0.,0.],"width":1.4,"height":0.6}]});{let state=h.state();let mut m=state.behaviors.borrow_mut();m.chest_stealer.interacted.insert([3,0,0]);m.storage_esp.categories[0].tracers=true;}
 let v=render(&h,&input);assert_eq!(v["models"].as_array().unwrap().len(),1);assert_eq!(v["body"]["targets"],json!([[7,0xff0064ffu32]]));assert_eq!(v["body"]["quads"].as_array().unwrap().len(),6);assert_eq!(v["plain"]["lines"].as_array().unwrap().len(),3);{let state=h.state();let mut m=state.behaviors.borrow_mut();m.storage_esp.glow=false;}
 let v=render(&h,&input);assert!(v["models"].as_array().unwrap().is_empty());assert_eq!(v["body"]["quads"].as_array().unwrap().len(),12);assert!((v["body"]["quads"][0][0]["color"][3].as_f64().unwrap()-50./255.).abs()<1e-6);assert_eq!(v["plain"]["quads"].as_array().unwrap().len(),6);assert!((v["plain"]["quads"][0][0]["position"][0].as_f64().unwrap()-2.75).abs()<1e-6);{let state=h.state();let mut m=state.behaviors.borrow_mut();m.storage_esp.requires_chest_stealer=true;}
 assert!(render(&h,&input).is_null());{let state=h.state();state.behaviors.borrow_mut().chest_running=true;}assert!(!render(&h,&input).is_null());
 gpu_model_alpha_and_vanilla();
}
fn gpu_model_alpha_and_vanilla(){
 let instance=wgpu::Instance::default();let adapter=pollster::block_on(instance.request_adapter(&Default::default())).expect("GPU adapter");let(device,queue)=pollster::block_on(adapter.request_device(&Default::default())).unwrap();
 let layout=device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor{label:None,entries:&[wgpu::BindGroupLayoutEntry{binding:1,visibility:wgpu::ShaderStages::FRAGMENT,ty:wgpu::BindingType::Texture{sample_type:wgpu::TextureSampleType::Float{filterable:true},view_dimension:wgpu::TextureViewDimension::D2,multisampled:false},count:None},wgpu::BindGroupLayoutEntry{binding:2,visibility:wgpu::ShaderStages::FRAGMENT,ty:wgpu::BindingType::Sampler(wgpu::SamplerBindingType::Filtering),count:None}]});let pipeline=device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor{label:None,bind_group_layouts:&[Some(&layout)],..Default::default()});let mut renderer=storage_render::StorageRenderer::new(&device,wgpu::TextureFormat::Rgba8Unorm,false,&pipeline);
 let texture=device.create_texture(&wgpu::TextureDescriptor{label:None,size:wgpu::Extent3d{width:64,height:64,depth_or_array_layers:1},mip_level_count:1,sample_count:1,dimension:wgpu::TextureDimension::D2,format:wgpu::TextureFormat::Rgba8Unorm,usage:wgpu::TextureUsages::RENDER_ATTACHMENT|wgpu::TextureUsages::COPY_SRC,view_formats:&[]});let view=texture.create_view(&Default::default());let read=device.create_buffer(&wgpu::BufferDescriptor{label:None,size:64*256,usage:wgpu::BufferUsages::MAP_READ|wgpu::BufferUsages::COPY_DST,mapped_at_creation:false});let atlas=device.create_texture(&wgpu::TextureDescriptor{label:None,size:wgpu::Extent3d{width:1,height:1,depth_or_array_layers:1},mip_level_count:1,sample_count:1,dimension:wgpu::TextureDimension::D2,format:wgpu::TextureFormat::Rgba8Unorm,usage:wgpu::TextureUsages::TEXTURE_BINDING|wgpu::TextureUsages::COPY_DST,view_formats:&[]});let av=atlas.create_view(&Default::default());let sampler=device.create_sampler(&Default::default());let group=device.create_bind_group(&wgpu::BindGroupDescriptor{label:None,layout:&layout,entries:&[wgpu::BindGroupEntry{binding:1,resource:wgpu::BindingResource::TextureView(&av)},wgpu::BindGroupEntry{binding:2,resource:wgpu::BindingResource::Sampler(&sampler)}]});
 for(style,alpha)in[(1usize,255u8),(0,255),(1,0)]{let mut s=storage_esp::StorageEsp::default();s.style=style;let e=s.effect().unwrap();storage_render::begin_frame(&json!({"quads":[],"lines":[],"effect":{"style":e.style,"params":e.params,"accent":e.accent,"range":e.range,"opacity":e.opacity},"targets":[[7,0xff0064ffu32]]}).to_string());assert_eq!(storage_render::entity_color(7),Some(0xff0064ff));queue.write_texture(atlas.as_image_copy(),&[255,255,255,alpha],wgpu::TexelCopyBufferLayout{offset:0,bytes_per_row:Some(4),rows_per_image:None},atlas.size());let vertices=[[-0.6,-0.6,0.5],[0.6,-0.6,0.5],[0.6,0.6,0.5],[-0.6,0.6,0.5]].map(|pos|mesher::Vertex{pos,uv:[0.5;2],layer:0,color:0xffffffff,light:0,normal:[0;4],glint_uv:[0.;2]});storage_render::capture_entity(7,&vertices);renderer.prepare(&device,glam::Mat4::IDENTITY,glam::DVec3::ZERO,[64,64],false);assert!(renderer.pending());let mut encoder=device.create_command_encoder(&Default::default());{let _p=encoder.begin_render_pass(&wgpu::RenderPassDescriptor{color_attachments:&[Some(wgpu::RenderPassColorAttachment{view:&view,depth_slice:None,resolve_target:None,ops:wgpu::Operations{load:wgpu::LoadOp::Clear(wgpu::Color::TRANSPARENT),store:wgpu::StoreOp::Store}})],..Default::default()});}renderer.draw(&device,&mut encoder,&view,0.1,glam::DVec3::ZERO,glam::Mat4::IDENTITY,70.,&group);encoder.copy_texture_to_buffer(texture.as_image_copy(),wgpu::TexelCopyBufferInfo{buffer:&read,layout:wgpu::TexelCopyBufferLayout{offset:0,bytes_per_row:Some(256),rows_per_image:None}},texture.size());queue.submit([encoder.finish()]);read.slice(..).map_async(wgpu::MapMode::Read,|r|r.unwrap());device.poll(wgpu::PollType::wait_indefinitely()).unwrap();{let bytes=read.slice(..).get_mapped_range().unwrap();assert_eq!(bytes.chunks_exact(4).any(|p|p[3]>0),alpha!=0,"style={style} alpha={alpha}");}read.unmap();}
}
}
